def finish_task_run(resource: dict[str, Any]) -> None:
    spec = resource.get("spec") if isinstance(resource.get("spec"), dict) else {}
    inline = spec.get("inline")
    if isinstance(inline, str):
        for index, line in enumerate(inline.splitlines(), start=1):
            if line.startswith("FAIL:"):
                reason = line.removeprefix("FAIL:").strip()
                resource["status"] = {
                    "state": "Failed",
                    "detail": f"command {index} failed: {reason}",
                }
                return
    resource["status"] = {"state": "Succeeded"}


def finish_data_run(
    kind: str,
    resource: dict[str, Any],
    store: dict[str, dict[str, dict[str, Any]]],
) -> None:
    mesh_ref = get_path(resource, ["spec", "meshRef"])
    mesh = store["meshes"].get(mesh_ref) if isinstance(mesh_ref, str) else None
    if not isinstance(mesh, dict):
        resource["status"] = {
            "state": "Failed",
            "detail": f"mesh '{mesh_ref}' does not exist",
        }
        return
    stable = public_resource(upgrade_stored_resource(mesh))["status"].get("stable") is True
    if not stable:
        resource["status"] = {
            "state": "Unknown",
            "detail": f"mesh '{mesh_ref}' is not stable",
        }
        return
    resource["status"] = {"state": "Succeeded"}


def public_one_shot(kind: str, resource: dict[str, Any]) -> dict[str, Any]:
    public = copy.deepcopy(upgrade_stored_one_shot(resource))
    status = public.get("status") if isinstance(public.get("status"), dict) else {}
    state = status.get("state", "Initializing")
    projected_status = {"state": state}
    if state in {"Failed", "Unknown"} and isinstance(status.get("detail"), str) and status["detail"]:
        projected_status["detail"] = status["detail"]
    if kind == "snapshot" and state == "Succeeded" and isinstance(status.get("storageRef"), str) and status["storageRef"]:
        projected_status["storageRef"] = status["storageRef"]
    public["status"] = projected_status
    return public


